{
  "application": "ppt-generation",
  "case_id": "case-paper-diatool-dpo",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 8,
    "audience": "ML researchers and NLP engineers working on tool-augmented LLMs and RLHF alignment",
    "tone": "technical, analytical, concise"
  },
  "brief": {
    "title": "DiaTool-DPO: Enhancing Tool-Augmented LLM Dialogue via Direct Preference Optimization",
    "one_liner": "A novel DPO-based method that models TA-LLM interactions as an MDP with 5 dialogue states and 3 query types, automatically constructing preference pairs to improve slot-filling and tool call rejection without human labeling.",
    "goal": "Understand how DiaTool-DPO formulates tool-use dialogue as a reinforcement learning problem, how its paired trajectory dataset is constructed, and how it achieves near-GPT-4o conversational performance on smaller open-source models."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "DiaTool-DPO: Multi-Turn DPO for Tool-Augmented LLMs",
      "objective": "Cover slide with paper title and key tagline about improving TA-LLM dialogue flow via direct preference optimization with automatic paired trajectory construction."
    },
    {
      "id": "problem-motivation",
      "title": "SFT Alone Fails to Teach Slot-Filling and Tool Rejection",
      "objective": "Explain the core problem: TA-LLMs trained only with SFT struggle with incomplete queries (missing arguments) and out-of-scope requests, leading to hallucinated tool calls. Describe the three failure modes — failing to ask follow-up questions, making hallucinated tool invocations, and failing to reject inappropriate tool calls — and motivate the need for preference optimization."
    },
    {
      "id": "five-state-mdp",
      "title": "Modeling TA-LLM Dialogue as a 5-State Markov Decision Process",
      "objective": "Visualize the 5 internal states (Initial, Tool Selected w/o Complete Slots, Tool Selected w/ Complete Slots, Wait for Tool Response, Complete) and their transitions. Reference the state diagram from figure_1.jpg."
    },
    {
      "id": "three-query-types",
      "title": "Three Query Types Define Distinct State Trajectories",
      "objective": "Show the three query types and their state trajectories: Type 1 (1→3→4→5, sufficient info), Type 2 (1→(2*N)→3→4→5, incomplete info), Type 3 (1→1, out-of-scope). Use a compact table mapping query type to trajectory and example."
    },
    {
      "id": "dataset-construction",
      "title": "Automatic Paired Trajectory Construction Without Human Labels",
      "objective": "Present the DiaTool-DPO dataset construction: chosen vs. rejected trajectories for each query type, learning lessons (prevent redundant slot-filling, prevent slot hallucination, tool call reject/accept). Display the dataset composition table with counts and difficulty levels."
    },
    {
      "id": "benchmark-results",
      "title": "SFT + DiaTool-DPO Achieves Best Macro Average Across All Models",
      "objective": "Show the main results table comparing DiaTool-DPO-only, SFT-only, and SFT + DiaTool-DPO across Prop.-8B, Prop.-3.1B, and LLaMA-3-8B on Call, Completion, Slot, Relevance, Micro Avg, and Macro Avg metrics. Highlight that SFT + DiaTool-DPO consistently achieves the highest Macro Avg."
    },
    {
      "id": "llama-performance-gains",
      "title": "LLaMA-3-8B: +43.5% Slot Accuracy and +10.5% Relevance with DiaTool-DPO",
      "objective": "Focus on the LLaMA-3-8B results showing dramatic improvements in Slot (0.639→0.917) and Relevance (0.826→0.913) when adding DiaTool-DPO to SFT. Use a bar chart or before/after comparison to emphasize the gains."
    },
    {
      "id": "takeaways-implications",
      "title": "Key Takeaways: RL-Based Dialogue Control for Production TA-LLMs",
      "objective": "Summarize 4-5 key findings: MDP formulation enables systematic trajectory pairing; automatic dataset construction eliminates human labeling; DPO complements SFT for dialogue control; approach is language-agnostic; opens path to GPT-4o-level conversational tool use on smaller models."
    }
  ]
}

