<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>DiaTool-DPO: Multi-Turn DPO for Tool-Augmented LLMs</title>

    <!-- Fonts: Syne (display) + IBM Plex Sans (body) + IBM Plex Mono (code/data) -->
    <link rel="preconnect" href="https://fonts.googleapis.com">
